-- Read-only application metadata; never exports account rows or private links.
select jsonb_build_object(
 'storage_rls',(select jsonb_build_object('rls',relrowsecurity,'force_rls',relforcerowsecurity) from pg_class where oid='storage.objects'::regclass),
 'client_roles',(select jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'bypass_rls',rolbypassrls,'inherit',rolinherit) order by rolname) from pg_roles where rolname in ('anon','authenticated','service_role')),
 'client_memberships',(select coalesce(jsonb_agg(jsonb_build_object('member',member_role.rolname,'role',granted_role.rolname,'admin_option',m.admin_option) order by member_role.rolname,granted_role.rolname),'[]') from pg_auth_members m join pg_roles member_role on member_role.oid=m.member join pg_roles granted_role on granted_role.oid=m.roleid where member_role.rolname in ('anon','authenticated','service_role')),
 'columns',(select jsonb_agg(to_jsonb(x) order by table_name,ordinal_position) from (select table_name,column_name,ordinal_position,data_type,udt_name,is_nullable,column_default from information_schema.columns where table_schema='public') x),
 -- PostgreSQL 18 catalogs NOT NULL separately; columns.is_nullable checks it on both 17 and 18.
 'constraints',(select jsonb_agg(to_jsonb(x) order by table_name,name) from (select c.conrelid::regclass::text table_name,c.conname name,c.contype type,c.convalidated validated,pg_get_constraintdef(c.oid) definition from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname='public' and c.contype <> 'n') x),
 'functions',(select jsonb_agg(to_jsonb(x) order by schema,name,args) from (select n.nspname schema,p.proname name,pg_get_function_identity_arguments(p.oid) args,pg_get_functiondef(p.oid) definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private','workify_private') and p.prokind='f') x),
 'function_permissions',(select jsonb_agg(to_jsonb(x) order by schema,name,args,role) from (select n.nspname schema,p.proname name,pg_get_function_identity_arguments(p.oid) args,r.role,has_function_privilege(r.role,p.oid,'execute') execute from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join (values ('anon'),('authenticated'),('service_role')) r(role) where n.nspname in ('public','private','workify_private') and p.prokind='f') x),
 'policies',(select jsonb_agg(to_jsonb(x) order by schemaname,tablename,policyname) from (select * from pg_policies where schemaname in ('public','storage')) x),
 'triggers',(select jsonb_agg(to_jsonb(x) order by table_name,name) from (select c.oid::regclass::text table_name,t.tgname name,pg_get_triggerdef(t.oid) definition from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where (n.nspname='public' or (n.nspname='auth' and c.relname='users')) and not t.tgisinternal) x),
 'grants',(select jsonb_agg(to_jsonb(x) order by table_name,grantee,privilege_type) from (select table_name,grantee,privilege_type from information_schema.role_table_grants where table_schema='public' and grantee<>'postgres') x),
 'tables',(select jsonb_agg(to_jsonb(x) order by name) from (select c.relname name,c.relrowsecurity rls,c.relforcerowsecurity force_rls from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r') x),
 'indexes',(select jsonb_agg(to_jsonb(x) order by tablename,indexname) from (select tablename,indexname,indexdef from pg_indexes where schemaname='public') x),
 'column_acls',(select coalesce(jsonb_agg(jsonb_build_object('table_name',c.relname,'column_name',a.attname,'acl',a.attacl::text) order by c.relname,a.attname),'[]') from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and a.attnum>0 and not a.attisdropped and a.attacl is not null),
 'storage_bucket',(select jsonb_build_object('id',id,'name',name,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types) from storage.buckets where id='avatars')
) as snapshot;
